const {test,expect}=require('@playwright/test');
const releaseVersion=require('../package.json').version;
test.beforeEach(async({page},info)=>{if(!info.tags.includes('@background-autosave'))await page.addInitScript(()=>{globalThis.__WORKMOIRE_TEST_MANUAL_SAVE__=true;});});
// Existing editor tests explicitly exercise manual saves; default-on behavior has its own coverage.
const pixel=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX1cAAAAASUVORK5CYII=','base64');
async function login(page){await page.goto('/');await page.locator('#auth-username').fill('demo-reader');await page.locator('#auth-password').fill('synthetic-password');await page.locator('#auth-submit').click();await expect(page.locator('#item-list')).toBeVisible();await expect(page.locator('#list-total')).toContainText('份文档');}
async function blank(page,title){await page.locator('#new-document').click();await page.locator('[data-template="blank"]').click();await page.locator('#edit-title').fill(title);await expect(page.locator('.rich-document')).toHaveAttribute('contenteditable','true');}
async function setContent(page,text){await page.evaluate(text=>state.editor.setValue(text),text);}
async function content(page){return page.evaluate(()=>state.editor.getValue());}
async function native(page){return page.evaluate(()=>state.editor.getNative());}
async function save(page){await page.locator('#save-content').click();await expect(page.locator('#save-state')).toHaveText('已保存');}
async function insert(page,command){await page.locator('.editor-toolbar .block-insert-menu > summary').click();await page.locator('.editor-toolbar .insert-options [data-command="'+command+'"]').click();}
async function reopen(page,id){await page.reload();await page.locator('[data-open="'+id+'"]').click();await expect(page.locator('.rich-document')).toBeVisible();}

test('legacy documents open as native editable blocks and retain math, code, tables and tasks',async({page})=>{
 const errors=[];page.on('pageerror',error=>errors.push(error.message));await login(page);await expect(page.locator('.main-nav .nav-item')).toHaveCount(3);
 await page.locator('[data-open="1"]').click();await expect(page.locator('.rich-document')).toHaveAttribute('contenteditable','true');await expect(page.locator('#save-state')).toHaveText('已保存');await expect(page.locator('.rich-bubble-menu')).toBeHidden();expect(await page.evaluate(()=>document.documentElement.scrollHeight)).toBeLessThanOrEqual(1000);
 await expect(page.locator('.rich-document .katex')).toHaveCount(2);await expect(page.locator('.rich-document table')).toHaveCount(1);await expect(page.locator('.native-code-block .hljs-keyword').first()).toBeVisible();await expect(page.locator('.cm-content')).toHaveCount(0);
 await page.locator('.rich-document li[data-type="taskItem"] input').first().check();await expect.poll(()=>content(page)).toContain('- [x] 比较局部窗口');await save(page);
 const id=await page.evaluate(()=>state.current.id);await reopen(page,id);await expect(page.locator('.rich-document li[data-type="taskItem"] input').first()).toBeChecked();await expect(page.locator('.rich-document .katex')).toHaveCount(2);
 await page.screenshot({path:'artifacts/rich/editor-desktop.png',fullPage:true});expect(errors).toEqual([]);
});

test('native bold, underline, color and alignment survive drafts, save and reload',async({page})=>{
 await login(page);await blank(page,'浏览器测试：富文本格式与草稿');await page.locator('.rich-document').click();await page.keyboard.insertText('中文与 English');await page.keyboard.press('Control+a');await expect(page.locator('.rich-bubble-menu')).toBeVisible();
 await page.locator('.editor-toolbar [data-command="bold"]').click();await page.locator('.editor-toolbar [data-command="underline"]').click();await expect(page.locator('.rich-document strong')).toContainText('中文');await expect(page.locator('.rich-document u')).toContainText('English');
 await page.locator('.text-color-menu > summary').click();await page.locator('#text-color').fill('#2458c5');await page.locator('.editor-toolbar [data-command="align-center"]').click();await expect(page.locator('.rich-document > p').first()).toHaveCSS('text-align','center');
 await save(page);const id=await page.evaluate(()=>state.current.id);const before=await native(page);await reopen(page,id);expect((await native(page)).document).toEqual(before.document);
 await page.locator('.rich-document').click();await page.keyboard.press('Control+End');await page.keyboard.insertText(' 草稿新增内容');await page.waitForTimeout(1000);
 page.once('dialog',dialog=>dialog.accept());await page.locator('[data-page="papers"]').click();await page.locator('[data-page="documents"]').click();await page.locator('[data-open="'+id+'"]').click();await page.locator('#restore-draft').click();await expect(page.locator('.rich-document')).toContainText('草稿新增内容');await expect(page.locator('.rich-document u')).toBeVisible();await save(page);
});

test('slash insertion and editable table rows, columns and widths persist',async({page})=>{
 await login(page);await blank(page,'浏览器测试：表格');await page.locator('.rich-document').click();await page.keyboard.type('/table');await expect(page.locator('.rich-slash-menu')).toBeVisible();await page.locator('.rich-slash-menu button').filter({hasText:'可直接编辑'}).click();
 const table=page.locator('.rich-document table');await expect(table.locator('tr')).toHaveCount(3);await table.locator('th').first().click();await page.keyboard.insertText('方法');await page.keyboard.press('Tab');await page.keyboard.insertText('结果');
 await expect(page.locator('#table-toolbar')).toBeVisible();await page.locator('#table-toolbar [data-command="row-after"]').click();await expect(table.locator('tr')).toHaveCount(4);await page.locator('#table-toolbar [data-command="column-after"]').click();await expect(table.locator('tr').first().locator('th,td')).toHaveCount(4);
 const cell=await table.locator('tr').first().locator('th,td').first().boundingBox();await page.mouse.move(cell.x+cell.width-1,cell.y+10);await page.mouse.down();await page.mouse.move(cell.x+cell.width+55,cell.y+10,{steps:6});await page.mouse.up();
 await expect.poll(async()=>JSON.stringify((await native(page)).document)).toMatch(/"colwidth":\[\d+/);await save(page);const id=await page.evaluate(()=>state.current.id),before=await native(page);await reopen(page,id);expect((await native(page)).document).toEqual(before.document);await expect(page.locator('.rich-document table')).toContainText('方法');await expect(page.locator('.rich-document table')).toContainText('结果');
});

test('formula dialog edits rendered equations and inline input rules create real math nodes',async({page})=>{
 await login(page);await blank(page,'浏览器测试：公式');await insert(page,'formula');const equation='\\sum_{i=1}^{n}i=\\frac{n(n+1)}{2}';await page.locator('.math-dialog textarea').fill(equation);await expect(page.locator('.math-dialog-preview .katex')).toBeVisible();await page.locator('.math-dialog button[type="submit"]').click();await expect(page.locator('.native-block-math .katex')).toBeVisible();
 await page.locator('.native-block-math').click();await page.locator('.math-dialog textarea').fill('E=mc^2');await page.locator('.math-dialog button[type="submit"]').click();await expect(page.locator('.native-block-math')).toHaveAttribute('data-latex','E=mc^2');
 await page.locator('.rich-document > p').last().click();await page.keyboard.type('$x^2$');await expect(page.locator('.native-inline-math')).toBeVisible();await save(page);const id=await page.evaluate(()=>state.current.id);await reopen(page,id);await expect(page.locator('.native-block-math')).toHaveAttribute('data-latex','E=mc^2');await expect(page.locator('.native-inline-math')).toHaveAttribute('data-latex','x^2');
});

test('inline code at the start of a paragraph leaves room for ordinary text before it',async({page})=>{
 await page.addInitScript(()=>Object.defineProperty(navigator,'platform',{value:'MacIntel'}));
 await login(page);await blank(page,'浏览器测试：行内代码前插入文字');await setContent(page,'sample()');await page.evaluate(()=>{state.editor.tiptap.commands.setTextSelection({from:1,to:9});state.editor.tiptap.view.focus();});await expect(page.locator('.rich-document')).toBeFocused();await page.keyboard.press('Meta+e');await expect(page.locator('.rich-document p > code')).toHaveText('sample()');
 const code=page.locator('.rich-document p > code');const bounds=await code.boundingBox();await page.mouse.click(bounds.x+1,bounds.y+bounds.height/2);await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.state.selection.empty)).toBe(true);await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.state.selection.$from.parentOffset)).toBe(0);await page.keyboard.press('Tab');await expect(page.locator('.rich-document > p').first()).toHaveAttribute('data-block-indent','1');await page.keyboard.press('Shift+Tab');await page.keyboard.press('Space');await page.keyboard.insertText('说明 ');await expect(code).toHaveText('sample()');await page.keyboard.press('Meta+b');await page.keyboard.insertText('加粗');await expect(page.locator('.rich-document strong')).toHaveText('加粗');await page.keyboard.press('Meta+b');await expect.poll(()=>page.locator('.rich-document > p').first().textContent()).toBe(' 说明 加粗sample()');expect(await content(page)).not.toMatch(/[\u200b\ufeff]/);await save(page);const id=await page.evaluate(()=>state.current.id),before=await native(page);await reopen(page,id);expect((await native(page)).document).toEqual(before.document);await expect(code).toHaveText('sample()');await expect.poll(()=>page.locator('.rich-document > p').first().textContent()).toBe(' 说明 加粗sample()');
});

test('inline code keyboard boundaries leave code intact and never insert phantom spacer characters',async({page})=>{
 await login(page);await blank(page,'浏览器测试：行内代码边界');await setContent(page,'`sample()`');await save(page);const id=await page.evaluate(()=>state.current.id);await reopen(page,id);const code=page.locator('.rich-document p > code');
 const caret=async position=>{await page.evaluate(position=>{state.editor.tiptap.commands.setTextSelection(position);state.editor.tiptap.view.focus();},position);await expect(page.locator('.rich-document')).toBeFocused();};
 await caret(1);const initial=await native(page);await page.evaluate(()=>state.editor.tiptap.commands.setCode());await expect(page.locator('.editor-toolbar [data-command="inline-code"]')).toHaveAttribute('aria-pressed','true');await page.keyboard.press('ArrowLeft');await expect(page.locator('.editor-toolbar [data-command="inline-code"]')).toHaveAttribute('aria-pressed','false');await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.state.selection.from)).toBe(1);expect((await native(page)).document).toEqual(initial.document);await page.keyboard.insertText('Before ');await expect(code).toHaveText('sample()');await page.keyboard.press('Control+z');await expect(page.locator('.rich-document > p').first()).toHaveText('sample()');expect((await native(page)).document).toEqual(initial.document);
 await caret(9);await page.evaluate(()=>state.editor.tiptap.commands.setCode());await expect(page.locator('.editor-toolbar [data-command="inline-code"]')).toHaveAttribute('aria-pressed','true');await page.keyboard.press('ArrowRight');await expect(page.locator('.editor-toolbar [data-command="inline-code"]')).toHaveAttribute('aria-pressed','false');expect((await native(page)).document).toEqual(initial.document);await page.keyboard.insertText(' after');await expect(code).toHaveText('sample()');await expect(page.locator('.rich-document > p').first()).toHaveText('sample() after');await caret(3);await page.keyboard.insertText('X');await expect(code).toHaveText('saXmple()');expect(await content(page)).not.toMatch(/[\u200b\ufeff]/);await save(page);await reopen(page,id);await expect(code).toHaveText('saXmple()');
});

test('inline code boundaries accept native Chinese composition in headings, lists and table cells',async({page})=>{
 await login(page);await blank(page,'浏览器测试：行内代码中文输入');const cdp=await page.context().newCDPSession(page);
 for(const body of ['`sample()`','## `sample()`','- `sample()`','| Code |\n| --- |\n| `sample()` |']){
  await setContent(page,body);await page.evaluate(()=>{let first;state.editor.tiptap.state.doc.descendants((node,pos)=>{if(first===undefined&&node.isText&&node.marks.some(mark=>mark.type.name==='code'))first=pos;});state.editor.tiptap.commands.setTextSelection(first);state.editor.tiptap.view.focus();});await expect(page.locator('.rich-document')).toBeFocused();const code=page.locator('.rich-document code');
  for(const text of ['ce','c']){await cdp.send('Input.imeSetComposition',{text,selectionStart:text.length,selectionEnd:text.length});await expect.poll(()=>page.evaluate(()=>state.editor.getText())).toContain(text+'sample()');}
  await cdp.send('Input.insertText',{text:'前'});await expect.poll(()=>page.evaluate(()=>state.editor.isComposing())).toBe(false);await expect(code).toHaveText('sample()');const data=await native(page);expect(JSON.stringify(data)).not.toMatch(/[\u200b\ufeff]/);await expect.poll(()=>page.evaluate(()=>state.editor.getText())).toContain('前sample()');
 }
});

test('Tab indents paragraphs and headings while retaining editor focus, rich marks and undo',async({page})=>{
 await login(page);await blank(page,'浏览器测试：Tab 缩进');await setContent(page,'**第一段**\n\n## 第二段\n\n第三段');await page.locator('.rich-document > p').first().click();await page.keyboard.press('Home');const before=await native(page);await page.keyboard.press('Tab');await expect(page.locator('.rich-document > p').first()).toHaveAttribute('data-block-indent','1');await expect(page.locator('.rich-document')).toBeFocused();await expect(page.locator('.rich-document strong')).toHaveText('第一段');await page.keyboard.press('Control+z');await expect(page.locator('.rich-document > p').first()).not.toHaveAttribute('data-block-indent');expect((await native(page)).document).toEqual(before.document);await page.keyboard.press('Control+Shift+z');await expect(page.locator('.rich-document > p').first()).toHaveAttribute('data-block-indent','1');await page.keyboard.press('Shift+Tab');await expect(page.locator('.rich-document > p').first()).not.toHaveAttribute('data-block-indent');await page.keyboard.press('Shift+Tab');await expect(page.locator('.rich-document')).toBeFocused();
 await page.evaluate(()=>{const doc=state.editor.tiptap.state.doc;state.editor.tiptap.commands.setTextSelection({from:1,to:doc.child(0).nodeSize+doc.child(1).nodeSize-1});});await page.keyboard.press('Tab');await expect(page.locator('.rich-document > p').first()).toHaveAttribute('data-block-indent','1');await expect(page.locator('.rich-document h2')).toHaveAttribute('data-block-indent','1');await expect(page.locator('.rich-document > p').last()).not.toHaveAttribute('data-block-indent');await save(page);const id=await page.evaluate(()=>state.current.id);await reopen(page,id);await expect(page.locator('.rich-document h2')).toHaveAttribute('data-block-indent','1');await page.locator('[data-mode="read"]').click();await expect(page.locator('.rich-document h2')).toHaveAttribute('data-block-indent','1');await page.locator('[data-mode="write"]').click();await page.locator('.rich-document > p').last().click();await page.keyboard.press('Escape');await expect(page.locator('#heading-tool')).toBeFocused();
});

test('Tab nests lists and indents whole code lines without replacing selected source',async({page})=>{
 await login(page);await blank(page,'浏览器测试：列表与代码缩进');
 for(const body of ['- First\n- Second','- [ ] First\n- [ ] Second']){
  await setContent(page,body);await page.locator('.rich-document li p').last().click();await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.state.selection.$from.parent.textContent)).toBe('Second');await page.keyboard.press('Tab');await expect(page.locator('.rich-document li li')).toHaveCount(1);await expect(page.locator('.rich-document li li')).toContainText('Second');await expect(page.locator('.rich-document')).toBeFocused();await page.keyboard.press('Shift+Tab');await expect(page.locator('.rich-document li li')).toHaveCount(0);await page.locator('.rich-document li p').first().click();await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.state.selection.$from.parent.textContent)).toBe('First');const first=await native(page);await page.keyboard.press('Tab');expect((await native(page)).document).toEqual(first.document);await expect(page.locator('.rich-document')).toBeFocused();
 }
 await setContent(page,'```python\nalpha()\nbeta()\ngamma()\n```');
 const range=async(from,to=from)=>{await page.evaluate(({from,to})=>{let start;state.editor.tiptap.state.doc.descendants((node,pos)=>{if(start===undefined&&node.type.name==='codeBlock')start=pos+1;});state.editor.tiptap.commands.setTextSelection({from:start+from,to:start+to});state.editor.tiptap.view.focus();},{from,to});await expect(page.locator('.rich-document')).toBeFocused();};
 const code=()=>page.locator('.native-code-block code').textContent();
 await range(0,8);await page.keyboard.press('Tab');await expect.poll(code).toBe('    alpha()\nbeta()\ngamma()');await page.keyboard.press('Shift+Tab');await expect.poll(code).toBe('alpha()\nbeta()\ngamma()');
 await range(2,10);await page.keyboard.press('Tab');await expect.poll(code).toBe('    alpha()\n    beta()\ngamma()');await page.keyboard.press('Shift+Tab');await expect.poll(code).toBe('alpha()\nbeta()\ngamma()');await range(0);await page.keyboard.press('Tab');await expect.poll(code).toBe('    alpha()\nbeta()\ngamma()');await page.keyboard.press('Control+z');await expect.poll(code).toBe('alpha()\nbeta()\ngamma()');await page.keyboard.press('Shift+Tab');await expect(page.locator('.rich-document')).toBeFocused();await save(page);const id=await page.evaluate(()=>state.current.id);await reopen(page,id);await expect.poll(code).toBe('alpha()\nbeta()\ngamma()');await page.evaluate(()=>state.editor.tiptap.commands.setContent({type:'doc',content:[{type:'codeBlock',attrs:{language:'python'},content:[{type:'text',text:'\n\talpha()\n  beta()'}]},{type:'paragraph'}]}));await range(0,1);await page.keyboard.press('Tab');await expect.poll(code).toBe('    \n\talpha()\n  beta()');await page.keyboard.press('Shift+Tab');await expect.poll(code).toBe('\n\talpha()\n  beta()');await range(1,18);await page.keyboard.press('Shift+Tab');await expect.poll(code).toBe('\nalpha()\nbeta()');
});

test('Tab keeps table navigation, respects IME composition, and indentation survives sharing',async({page,browser})=>{
 await login(page);await blank(page,'浏览器测试：Tab 边界');await insert(page,'table');const table=page.locator('.rich-document table');await table.locator('th').first().click();await page.keyboard.press('Shift+Tab');await expect(page.locator('.rich-document')).toBeFocused();await page.keyboard.insertText('First');await page.keyboard.press('Tab');await page.keyboard.insertText('Second');await expect(table.locator('th').nth(1)).toContainText('Second');await table.locator('td').last().click();await expect.poll(()=>page.evaluate(()=>state.editor.tiptap.can().goToNextCell())).toBe(false);await page.keyboard.press('Tab');await expect(table.locator('tr')).toHaveCount(4);await expect(page.locator('.rich-document')).toBeFocused();
 await setContent(page,'## 缩进标题\n\n正文');await page.locator('.rich-document h2').click();const before=await native(page);const prevented=await page.evaluate(()=>{const event=new KeyboardEvent('keydown',{key:'Tab',isComposing:true,bubbles:true,cancelable:true});document.querySelector('.rich-document').dispatchEvent(event);return event.defaultPrevented;});expect(prevented).toBe(false);expect((await native(page)).document).toEqual(before.document);await page.keyboard.press('Tab');await page.keyboard.press('Tab');await save(page);
 await page.locator('#share-document').click();await page.locator('#share-create').click();await expect(page.locator('#share-link')).toHaveValue(/\/s\/[A-Za-z0-9_-]{43}$/);const share={url:await page.locator('#share-link').inputValue(),password:await page.locator('#share-owner-password').inputValue()};const context=await browser.newContext(),guest=await context.newPage();try{await unlockShare(guest,share);await expect(guest.locator('.rich-document h2')).toHaveAttribute('data-block-indent','2');await expect(guest.locator('.rich-document h2')).toHaveCSS('margin-inline-start',/px$/);}finally{await context.close();}
});

