function chosenPDF(label,extraText=''){
 const stream='BT /F1 12 Tf 30 740 Td ('+label+') Tj 0 -25 Td (Selected PDF evidence: research questions, methods, limitations and reproducible results.) Tj 0 -25 Td (This text is a synthetic fixture. It must remain the analysis source when a URL is also supplied.) Tj '+extraText+' ET';
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 800] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+Buffer.byteLength(stream)+' >>\nstream\n'+stream+'\nendstream','<< /Title ('+label+') /Author (Synthetic PDF Author) >>'];
 let data='%PDF-1.4\n',offsets=[];objects.forEach((object,i)=>{offsets.push(Buffer.byteLength(data));data+=(i+1)+' 0 obj\n'+object+'\nendobj\n';});const xref=Buffer.byteLength(data);data+='xref\n0 7\n0000000000 65535 f \n'+offsets.map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 7 /Root 1 0 R /Info 6 0 R >>\nstartxref\n'+xref+'\n%%EOF\n';return Buffer.from(data);
}
