test('long PDF text stops at the evidence limit and still previews, analyzes and saves',async({page})=>{
 await login(page);await paperEntry(page);const dialog=page.locator('.paper-import-dialog');
 // A large final chunk exercises cancellation after the worker has closed its sink.
 const words='Bounded synthetic paper evidence with methods and limitations. ';
 const extra=Array.from({length:61},()=> '/F1 0.1 Tf 1 0 0 1 30 600 Tm ('+words.repeat(17)+') Tj').join(' ');
 const bytes=chosenPDF('LONG_SYNTHETIC_PAPER',extra);
 await dialog.locator('#paper-pdf-input').setInputFiles({name:'long-paper.pdf',mimeType:'application/pdf',buffer:bytes});await dialog.locator('#paper-prepare').click();await expect(dialog.locator('#paper-title')).toHaveValue('LONG_SYNTHETIC_PAPER');await expect(dialog.locator('.paper-import-error')).toBeEmpty();await expect(dialog.locator('.paper-text-status')).toContainText('部分文字');await expect(dialog.locator('.paper-transfer-progress')).toContainText('PDF 上传完成');await expect(dialog.locator('#paper-generate')).toBeEnabled();await expect(dialog.frameLocator('iframe').locator('.page canvas')).toBeVisible();
 const request=page.waitForRequest(r=>r.url().endsWith('/api/papers/draft'));await dialog.locator('#paper-generate').click();const payload=(await request).postDataJSON();expect(payload.truncated).toBe(true);expect(payload.text.length).toBeGreaterThan(59000);expect(payload.text.length).toBeLessThanOrEqual(60000);expect(payload.text).toContain('Bounded synthetic paper');await expect(dialog.locator('.paper-analysis-result')).toBeVisible();await dialog.locator('#paper-use').click();await save(page);const id=await page.evaluate(()=>state.current.id),files=(await (await page.request.get('/api/files?item_id='+id)).json()).files;expect(files).toHaveLength(1);expect(await (await page.request.get('/files/'+files[0].id)).body()).toEqual(bytes);
});

