async function resizeTableColumn(page,cell,delta){const bounds=await cell.boundingBox();await page.mouse.move(bounds.x+bounds.width-1,bounds.y+12);await page.mouse.down();await page.mouse.move(bounds.x+bounds.width+delta,bounds.y+12,{steps:8});await page.mouse.up();}
async function tableSize(table){return table.evaluate(el=>({width:el.getBoundingClientRect().width,viewport:el.parentElement.clientWidth,overflow:el.parentElement.scrollWidth,scrollLeft:el.parentElement.scrollLeft,columns:Array.from(el.querySelectorAll(':scope > colgroup > col'),col=>col.getBoundingClientRect().width)}));}

