 await setContent(page,'## 阅读笔记\n\n'+('这是个人理解，保留笔记的编辑和阅读位置。\n\n'.repeat(24))+'## 原文附件\n\n@[pdf](/files/'+('c'.repeat(32))+'?inline=1)\n');await save(page);const id=await page.evaluate(()=>state.current.id);await reopen(page,id);
