async function pdfPage(pdf,pageNumber){await pdf.locator('#pdf-page').fill(String(pageNumber));await pdf.locator('#pdf-page').press('Enter');await expect.poll(()=>pdf.locator('body').evaluate(()=>window.WorkmoirePDF.snapshot().page)).toBe(pageNumber);}
async function selectPdfEvidence(pdf,pageNumber){await pdfPage(pdf,pageNumber);const line=pdf.locator('.page[data-page-number="'+pageNumber+'"] .textLayer span').filter({hasText:'PAGE_'+pageNumber+'_EVIDENCE:'});await expect(line).toBeVisible();await line.evaluate(el=>{const range=document.createRange();range.selectNodeContents(el);getSelection().removeAllRanges();getSelection().addRange(range);});await expect(pdf.locator('#pdf-insert-quote')).toBeEnabled();return line.textContent();}

