test('autosave pauses on a conflicting tab and keeps local drafts instead of overwriting the newer document',{tag:'@background-autosave'},async({page})=>{
 await login(page);await blank(page,'浏览器测试：自动保存冲突');await setContent(page,'原始正文');await save(page);await enableAutosave(page);const id=await page.evaluate(()=>state.current.id),stored=(await (await page.request.get('/api/items/'+id)).json()).item;
 await page.request.put('/api/items/'+id,{data:{...stored,content:'其他窗口的新版本',rich_content:null,base_updated_at:stored.updated_at}});await page.locator('.rich-document').click();await page.keyboard.press('Control+End');await page.keyboard.insertText(' 本窗口未保存的想法');await expect(page.locator('#conflict-notice')).toBeVisible();await expect(page.locator('#save-state')).toContainText('版本冲突');expect((await (await page.request.get('/api/items/'+id)).json()).item.content).toBe('其他窗口的新版本');expect(await page.evaluate(()=>readDraft(state.current)?.content)).toContain('本窗口未保存的想法');let writes=0;page.on('request',r=>{if(r.method()==='PUT'&&r.url().endsWith('/api/items/'+id))writes++});await page.keyboard.insertText(' 冲突后继续写');await page.waitForTimeout(2300);expect(writes).toBe(0);await expect(page.locator('#save-state')).toContainText('版本冲突');
});

test('autosave waits for native Chinese composition and resumes an offline draft after reconnecting',{tag:'@background-autosave'},async({page})=>{
 await login(page);await blank(page,'浏览器测试：自动保存输入与离线');await setContent(page,'原始正文');await save(page);const id=await page.evaluate(()=>state.current.id);await enableAutosave(page);await page.evaluate(()=>state.editor.tiptap.commands.focus('end'));await expect(page.locator('.rich-document')).toBeFocused();const cdp=await page.context().newCDPSession(page);let writes=0;page.on('request',r=>{if(r.method()==='PUT'&&r.url().endsWith('/api/items/'+id))writes++});
 await cdp.send('Input.imeSetComposition',{text:'qwe',selectionStart:3,selectionEnd:3});await expect.poll(()=>page.evaluate(()=>state.editor.isComposing())).toBe(true);await page.waitForTimeout(2300);expect(writes).toBe(0);await cdp.send('Input.insertText',{text:'输入完成'});await expect.poll(()=>page.evaluate(()=>state.editor.isComposing())).toBe(false);await expect(page.locator('#save-state')).toHaveText('已保存',{timeout:10000});expect((await (await page.request.get('/api/items/'+id)).json()).item.content).toContain('输入完成');
 await page.context().setOffline(true);await page.keyboard.insertText(' 离线补充');await expect(page.locator('#save-state')).toContainText('离线',{timeout:8000});await expect.poll(()=>page.evaluate(()=>readDraft(state.current)?.content||'')).toContain('离线补充');await page.context().setOffline(false);await expect(page.locator('#save-state')).toHaveText('已保存',{timeout:10000});expect((await (await page.request.get('/api/items/'+id)).json()).item.content).toContain('离线补充');
});

