test('background autosave keeps a server failure warning during typing and retries and clears only the latest saved content',{tag:'@background-autosave'},async({page})=>{
 await login(page);await page.evaluate(()=>openDocument(3,true));await expect(page.locator('.rich-document')).toBeVisible();let attempts=0,release,started;const held=new Promise(r=>release=r),entered=new Promise(r=>started=r);
 await page.route('**/api/items/3',async route=>{if(route.request().method()!=='PUT'){await route.continue();return;}attempts++;if(attempts===1){await route.fulfill({status:503,json:{error:'Synthetic service outage'}});return;}if(attempts===2){started();await held;}await route.continue();});
 await page.evaluate(()=>state.editor.tiptap.commands.focus('end'));await page.keyboard.insertText(' 服务异常前的修改');const warning=page.locator('#sync-warning');await expect(warning).toContainText('服务异常，自动保存失败');await expect(warning).toContainText('建议暂时停止编辑');await page.keyboard.insertText(' 警告持续');await expect(warning).toBeVisible();await entered;await page.keyboard.insertText(' 重试中继续写');await expect(warning).toBeVisible();await page.screenshot({path:'artifacts/rich/sync-server-warning.png'});release();
 await expect.poll(()=>page.evaluate(()=>state.baseline.content.includes('警告持续'))).toBe(true);await expect(warning).toBeVisible();await expect(warning).toBeHidden({timeout:12000});expect((await (await page.request.get('/api/items/3')).json()).item.content).toContain('重试中继续写');expect(attempts).toBeGreaterThanOrEqual(3);
});

test('background autosave recovers a lost creation response without duplicates or losing subsequent edits',{tag:'@background-autosave'},async({page})=>{
 await login(page);const before=(await (await page.request.get('/api/items?limit=1')).json()).total;await blank(page,'自动新建重试');let first=true,createdId=null,keys=[];
 await page.route('**/api/items',async route=>{if(route.request().method()!=='POST'){await route.continue();return;}keys.push(route.request().postDataJSON().creation_key);if(first){first=false;const response=await route.fetch();createdId=(await response.json()).item.id;await route.abort('failed');return;}await route.continue();});await setContent(page,'首个创建请求中的正文');await expect(page.locator('#sync-warning')).toContainText('网络异常');await page.evaluate(()=>state.editor.tiptap.commands.focus('end'));await page.keyboard.insertText(' 响应丢失后继续写');await expect(page.locator('#sync-warning')).toBeVisible();
 await expect(page.locator('#sync-warning')).toBeHidden({timeout:12000});await expect(page.locator('#save-state')).toHaveText('已保存');expect(await page.evaluate(()=>state.current.id)).toBe(createdId);expect(new Set(keys).size).toBe(1);expect(keys.length).toBeGreaterThanOrEqual(2);expect((await (await page.request.get('/api/items?limit=1')).json()).total).toBe(before+1);expect((await (await page.request.get('/api/items/'+createdId)).json()).item.content).toContain('响应丢失后继续写');
});

