test('shared readers show a read-only right outline and mobile outline toggle',async({page,browser})=>{
 await login(page);await blank(page,'浏览器测试：分享目录');await setContent(page,'# 开始\n\n正文。\n\n## 方法设计\n\n正文。\n\n### 具体步骤\n\n正文。');await save(page);await page.locator('#share-document').click();await page.locator('#share-create').click();await expect(page.locator('#share-link')).toHaveValue(/^http:\/\/127\.0\.0\.1:8766\/s\/[A-Za-z0-9_-]{43}$/);const updated={url:await page.locator('#share-link').inputValue(),password:await page.locator('#share-owner-password').inputValue()};const context=await browser.newContext({viewport:{width:1440,height:1000}}),guest=await context.newPage();try{await unlockShare(guest,updated);await expect(guest.locator('#share-outline')).toBeVisible();await expect(guest.locator('#share-outline button')).toHaveText(['开始','方法设计','具体步骤']);await expect(guest.locator('.share-article')).toHaveCSS('grid-template-columns',/./);await expect(guest.locator('.rich-document')).toHaveAttribute('contenteditable','false');await guest.setViewportSize({width:390,height:844});await expect(guest.locator('#share-outline-toggle')).toBeVisible();await guest.locator('#share-outline-toggle').click();await expect(guest.locator('.share-outline')).toBeHidden();await guest.locator('#share-outline-toggle').click();await expect(guest.locator('.share-outline')).toBeVisible();await guest.locator('#share-outline button').nth(2).click();await expect(guest.locator('.rich-document h3')).toBeInViewport();await guest.screenshot({path:'artifacts/rich/shared-outline-mobile.png'});}finally{await context.close();}
});

test('history panel shows line changes and restores a selected saved version',{tag:'@history-ui'},async({page})=>{
 await login(page);await blank(page,'浏览器测试：历史改动面板');await setContent(page,'## 第一版\n\n旧正文');await page.locator('#save-content').click();await expect(page.locator('#save-state')).toHaveText('已保存');await setContent(page,'## 第二版\n\n新正文');await page.locator('#save-content').click();await expect(page.locator('#save-state')).toHaveText('已保存');await page.locator('#inspector-toggle').click();await page.locator('.inspector-details').filter({hasText:'历史版本'}).locator('summary').click();const rows=page.locator('.revision-row');await expect(rows).toHaveCount(1);await rows.first().click();const dialog=page.locator('.revision-preview-dialog');await expect(dialog).toBeVisible();await expect(dialog.locator('.revision-diff-removed').filter({hasText:'第一版'})).toBeVisible();await expect(dialog.locator('.revision-diff-added').filter({hasText:'第二版'})).toBeVisible();page.once('dialog',dialog=>dialog.accept());await dialog.locator('#revision-restore').click();await expect(page.locator('.revision-preview-dialog')).toBeHidden();
});
